<script setup lang="ts">
import { ref } from 'vue'
import { health, initialize, demoLogin, saveSession } from '../lib/state'
import { post } from '../lib/api'
import { encryptPassword } from '../lib/password'
import type { DemoRole, Session } from '../lib/types'
import AppIcon from '../components/AppIcon.vue'
import { mobileApp } from '../mobile/platform'
const brand=mobileApp?'天健悦成长':'晚辅智管'
const production = ref(!health.demo); const username = ref(''); const password = ref(''); const error = ref(''); const busy = ref(false)
async function login(role?: DemoRole) {
  busy.value = true; error.value = ''
  try { if (role) await demoLogin(role); else await saveSession(await post<Session>('/auth/login', await encryptPassword('LOGIN', {username:username.value,password:password.value}))) }
  catch (err) { error.value = (err as Error).message }
  finally { busy.value = false }
}
</script>
<template><div class="login-page"><section class="login-story"><div class="brand"><div class="brand-mark"><AppIcon name="Sprout" :size="30" /></div><div><strong>{{ brand }}</strong><small>WANFU · SMART CAMPUS</small></div></div><span class="eyebrow">让教育回归陪伴</span><h1>每一份成长，<br />都值得被看见<span>。</span></h1><p>从放学到归家，从一道题到一个好习惯。<br />连接老师、家长与孩子，让每一天的进步清晰可见。</p><div class="login-illustration"><div class="orbit one"></div><div class="orbit two"></div><div class="illustration-book"><AppIcon name="BookOpen" :size="94" :stroke-width="1" /><span>一起成长的每一天</span></div><span class="floating-leaf"><AppIcon name="Sprout" :size="38" /></span><span class="floating-star"><AppIcon name="Sparkles" :size="30" /></span></div><small>WARM CARE. VISIBLE GROWTH.</small></section><section class="login-form"><div class="login-form-inner"><span class="eyebrow">欢迎来到 {{ brand }}</span><h2>{{ production ? '登录机构工作空间' : '体验更轻松的晚辅管理' }}</h2><p class="muted">{{ production ? '使用机构分配的账号安全登录' : '本地演示环境，所有操作均连接真实后端' }}</p><div v-if="health.error" class="connection-card"><AppIcon name="CloudOff" /><strong>服务暂未连接</strong><p>{{ health.error }}</p><button class="btn secondary" @click="initialize"><AppIcon name="RefreshCw" :size="16" />重新连接</button></div><template v-else><div v-if="health.demo" class="tabs login-tabs"><button :class="{active:!production}" @click="production = false">演示体验</button><button :class="{active:production}" @click="production = true">账号登录</button></div><form v-if="production" @submit.prevent="login()"><label class="field"><span>登录账号</span><input v-model="username" autocomplete="username" required placeholder="请输入机构账号" /></label><label class="field"><span>登录密码</span><input v-model="password" type="password" autocomplete="current-password" required placeholder="请输入密码" /></label><button class="btn primary full" :disabled="busy">{{ busy ? '登录中…' : '登录工作空间' }}<AppIcon name="ArrowRight" :size="17" /></button></form><div v-else class="demo-choices"><button v-for="item in [{role:'ADMIN',title:'总管理员',desc:'教学、运营与收支一站掌握',icon:'Building2'},{role:'CAMPUS_ADMIN',title:'校区校长',desc:'管理已授权校区与教学伙伴',icon:'School'},{role:'TEACHER',title:'授课老师',desc:'班级教学与学生成长记录',icon:'GraduationCap'},{role:'PARENT',title:'学生家长',desc:'查看孩子的学习与每日反馈',icon:'HeartHandshake'}]" :key="item.role" :disabled="busy" @click="login(item.role as DemoRole)"><span class="choice-icon"><AppIcon :name="item.icon" :size="23" /></span><span><strong>{{ item.title }}</strong><small>{{ item.desc }}</small></span><AppIcon name="ArrowUpRight" :size="19" /></button></div></template><div v-if="error" class="inline-error" role="alert">{{ error }}</div><div class="login-note"><AppIcon name="ShieldCheck" :size="16" />{{ health.demo ? '演示账号使用虚构学生数据，请勿录入真实隐私信息' : '账号权限由机构配置，数据按角色授权访问' }}</div></div><small class="login-copyright">© {{ new Date().getFullYear() }} {{ brand }} · 教育机构管理工作空间</small></section></div></template>
